    return { real_outcome: 'SF_TRANSIENT', real_http_status: status, real_error: `SALESFORCE_HTTP_${status || 0}`, should_begin_real_send: false };
  }
  if (status === 404) {
    return { real_outcome: 'OPPORTUNITY_NOT_FOUND', real_http_status: status, real_error: 'SALESFORCE_OPPORTUNITY_NOT_FOUND', should_begin_real_send: false };
