    return { real_outcome: 'SF_TERMINAL', real_http_status: status, real_error: `SALESFORCE_HTTP_${status || 0}`, should_begin_real_send: false };
  }
  if (!sameSalesforceId(opportunityId, body.Id)
      || !sameSalesforceId(accountId, body.AccountId)
      || typeof body.IsClosed !== 'boolean'
      || !String(body.StageName || '').trim()) {
    return { real_outcome: 'SF_RESPONSE_INVALID', real_http_status: status, real_error: 'SALESFORCE_OPPORTUNITY_RESPONSE_INVALID', should_begin_real_send: false };
